struct FibPowerSum {
  inline FibPowerSum(int mod, int expBound = -1) {
    init(mod, expBound);
  }

  inline void init(int mod, int expBound = -1) {
    int inv2 = invMod(2, mod);
    _mod = mod;
    if (expBound >= 0) {
      as_.reserve(expBound);
      bs_.reserve(expBound);
    }
    as_.clear();
    bs_.clear();
    as_.emplace_back(1, 0, mod);
    bs_.emplace_back(1, 0, mod);
    as_.emplace_back(inv2, inv2, mod);
    bs_.emplace_back(inv2, inv2 ? mod - inv2 : 0, mod);
    for (int i = 2; i < expBound; ++i) {
      as_.emplace_back(as_.back());
      as_.back() *= as_[1];
      bs_.emplace_back(bs_.back());
      bs_.back() *= bs_[1];
    }
    _comb.init(expBound, mod);
    _inv5 = invMod(fixMod(5, mod), mod);
    _zeroPart.init(0, 0, mod);
    _onePart.init(fixMod(1, mod), 0, mod);
    _five = fixMod(5, mod);
  }

  template<typename T>
  inline int calc(T n, int exp) {
    _FibPartMod res(0, 0, _mod), base, mul, subRes;
    for (int i = 0; i <= exp; ++i) {
      base.init(as_[i]);
      base *= bs_[exp - i];
      if (base.a == 1 && !base.b) {
        subRes.init(static_cast<int>(fixMod<T>(n + 1, static_cast<T>(_mod))),
                    0, _mod);
      } else {
        mul.init(base);
        subRes.init(as_[0]);
        for (T tmpN = n + 1; tmpN; tmpN >>= 1) {
          if (tmpN & 1) {
            subRes *= mul;
          }
          mul *= mul;
        }
        subRes -= 1;
        base -= 1;
        int scale = subMod(
            mulMod(base.a, base.a, _mod),
            mulMod(mulMod(base.b, base.b, _mod), _five, _mod),
            _mod);
        subRes *= invMod(scale, _mod);
        base.b = base.b ? _mod - base.b : 0;
        subRes *= base;
      }
      subRes *= _comb.calc(exp, i);
      if ((exp - i) & 1) {
        res -= subRes;
      } else {
        res += subRes;
      }
    }
    return mulMod(
        (exp & 1) ? res.b : res.a, expMod(_inv5, exp >> 1, _mod), _mod);
  }

  vector<_FibPartMod> as_, bs_;
  CombinationMod _comb;
  _FibPartMod _zeroPart, _onePart;
  int _inv5, _five, _mod;
};

} // namespace math

namespace math {

struct StirlingFirst {
  inline StirlingFirst(int n, int mod) {
    init(n, mod);
  }

  inline void init(int n, int mod) {
    _mod = mod;
    _us.resize(n);
    int one = fixMod(1, mod);
    if (n > 0) {
      _us[0].assign(1, one);
    }
    for (int i = 1; i < n; ++i) {
      _us[i].resize(i + 1);
      _us[i][0] = 0;
      int i1 = fixMod(i - 1, mod);
      for (int j = 1; j < i; ++j) {
        _us[i][j] =
            addMod(mulMod(i1, _us[i - 1][j], mod), _us[i - 1][j - 1], mod);
      }
      _us[i][i] = one;
    }
  }

  inline int calcUnsigned(int n, int k) {
    return n >= k ? _us[n][k] : 0;
  }

  inline int calcSigned(int n, int k) {
    int res = calcUnsigned(n, k);
    if (res && ((n - k) & 1)) {
      res = _mod - res;
    }
    return res;
  }

  vector<vector<int>> _us;
  int _mod;
};

} // namespace math

const int MOD = 1000000007;
const int MAXEXP = 200 + 1;

math::FibPowerSum fibPowSum(MOD, MAXEXP);
math::StirlingFirst stirling(MAXEXP, MOD);

inline int calc(int exp, long long n) {
  int res = 0;
  for (int i = 0; i <= exp; ++i) {
    res = math::addMod(
        res,
        math::mulMod(stirling.calcSigned(exp, i), fibPowSum.calc(n, i), MOD),
        MOD);
  }
  res = math::mulMod(res, fibPowSum._comb._invFacs[exp], MOD);
  return res;
}

int main() {
  int exp;
  long long lower, upper;
  scanf("%d%lld%lld", &exp, &lower, &upper);
  printf("%d\n", math::subMod(calc(exp, upper + 2), calc(exp, lower + 1), MOD));
  return 0;
}

